edges = [
    (0,1),(0,4),(0,5),
    (1,2),(1,6),
    (2,3),(2,7),
    (3,4),(3,8),
    (4,9),
    (5,7),(5,8),
    (6,8),(6,9),
    (7,9)
]

# build adjacency
from collections import defaultdict
adj = defaultdict(set)
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

print("Degrees:", {i:len(adj[i]) for i in range(10)})

# check triangles
triangles = []
for u in range(10):
    for v in adj[u]:
        if v <= u: continue
        for w in adj[v]:
            if w <= u: continue
            if w in adj[u]:
                triangles.append((u,v,w))
print("Triangles:", triangles)

# check 4-cycles (simple cycles of length 4)
c4 = []
for a in range(10):
    for b in adj[a]:
        if b <= a: continue
        for c in adj[b]:
            if c <= a: continue
            for d in adj[c]:
                if d <= b: continue
                if d in adj[a] and d != b and d != c:
                    # ensure distinct
                    if len({a,b,c,d}) == 4:
                        c4.append(tuple(sorted((a,b,c,d))))
print("4-cycles (unique sets):", sorted(set(c4)))

# find shortest cycle length
import sys
shortest = sys.maxsize
best = []
for start in range(10):
    # BFS for cycle
    parent = {start: None}
    dist = {start: 0}
    q = [start]
    while q:
        u = q.pop(0)
        for v in adj[u]:
            if v not in dist:
                dist[v] = dist[u] + 1
                parent[v] = u
                q.append(v)
            elif parent[u] != v and parent[v] != u:
                # found a back edge
                cycle_len = dist[u] + dist[v] + 1
                if cycle_len < shortest:
                    shortest = cycle_len
                    best = [(u,v)]
                elif cycle_len == shortest:
                    best.append((u,v))
print("Shortest cycle length:", shortest)
